package ktanesolver.module.modded.regular.coffeebucks;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.coffeebucks.CoffeebucksInput.*;
class CoffeebucksSolverTest{private final CoffeebucksSolver s=new CoffeebucksSolver();@Test void returnsEveryDrinkTiedForMostPreferences(){var out=solve(new ModuleEntity(),new CoffeebucksInput("Alex",NameColor.BLUE,Sugar.DIABETIC_IN_WAITING,TimeOfDay.AFTERNOON,Stress.AGITATED,Size.VENTI,200,750));assertThat(out.drinks()).containsExactly("Twix Frappuccino","The Blue Drink","Liquid Cocaine");assertThat(out.quirkCommand()).isEqualTo("gluten");assertThat(out.projectedTipTotalCents()).isEqualTo(950);}@Test void marksOnlyTheCustomerThatReachesTenDollarsSolvedAndRecordsFinalPreferences(){var m=new ModuleEntity();var input=new CoffeebucksInput("Sam",NameColor.PINK,Sugar.LOADS,TimeOfDay.MORNING,Stress.STRESSED,Size.TALL,950,50);var result=(SolveSuccess<CoffeebucksOutput>)s.solve(new RoundEntity(),new BombEntity(),m,input);assertThat(result.solved()).isTrue();assertThat(result.output().drinks()).containsExactly("S’mores Hot Chocolate");assertThat(m.getState()).containsEntry("coffeebucksSugar","Loads").containsEntry("coffeebucksTime","Morning").containsEntry("coffeebucksStress","Stressed").containsEntry("coffeebucksSize","Tall");}@Test void keepsIntermediateCustomersOpenAndValidatesTipCounters(){var input=new CoffeebucksInput("Jo",NameColor.WHITE,Sugar.JUST_A_BIT,TimeOfDay.AFTERNOON,Stress.CALM,Size.SHORT,0,999);assertThat(((SolveSuccess<?>)s.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),input)).solved()).isFalse();assertThat(s.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new CoffeebucksInput("Jo",NameColor.WHITE,Sugar.JUST_A_BIT,TimeOfDay.AFTERNOON,Stress.CALM,Size.SHORT,0,49))).isInstanceOf(SolveFailure.class);}private CoffeebucksOutput solve(ModuleEntity m,CoffeebucksInput i){return((SolveSuccess<CoffeebucksOutput>)s.solve(new RoundEntity(),new BombEntity(),m,i)).output();}}
